	// resolve latest 'a' fetch
	resolvers.get('a')!([{ value: 'apple', label: 'Apple' }]);
	await Promise.resolve();
	expect(instance.filteredOptions).toEqual([{ value: 'apple', label: 'Apple' }, { value: 'banana', label: 'Banana' }]);
